import { test, expect } from '@playwright/test';

test.describe('Live Data Timestamp', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/live-data');
  });

  test('should display the last updated timestamp', async ({ page }) => {
    const timestamp = await page.getByRole('status', { name: /last updated/i });
    await expect(timestamp).toBeVisible();
  });

  test('should update the timestamp when new data is fetched', async ({ page }) => {
    const initialTimestamp = await page.getByRole('status', { name: /last updated/i }).innerText();

    // Simulate data fetch
    await page.evaluate(() => {
      // Mocking an API call that updates the timestamp
      window.fetch = async () => {
        return {
          json: async () => ({ updatedAt: new Date().toISOString() }),
        };
      };
    });

    await page.reload();

    const updatedTimestamp = await page.getByRole('status', { name: /last updated/i }).innerText();
    expect(updatedTimestamp).not.toEqual(initialTimestamp);
  });
});
